"use client";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

// ─────────────────────────────────────────────────────────────
// AP Audit Platform Software — Login Page v2
// Layout: Panel blanco (logo centrado + features) | Panel azul rey (glassmorphism)
// Actualizado: Junio 2026 — Logo transparente, sin fondo
// ─────────────────────────────────────────────────────────────

const LOGO_URI = "data:image/webp;base64,";

const FEATURES = [
  { title: "Auditoría integral",    desc: "Granjas · CEDIS · Rutas",        icon: "check"     },
  { title: "KPIs en tiempo real",   desc: "98 indicadores activos",          icon: "chart"     },
  { title: "Control de accesos",    desc: "MFA · Roles · Trazabilidad",      icon: "user"      },
  { title: "Cronograma 2026",       desc: "Planificación · Seguimiento",     icon: "calendar"  },
  { title: "Hallazgos COSO",        desc: "123 hallazgos · Marco estándar",  icon: "star"      },
  { title: "Dashboard ejecutivo",   desc: "27 granjas · Cundinamarca & Meta", icon: "grid"     },
];

function IconSVG({ name }: { name: string }) {
  const props = { width: 15, height: 15, viewBox: "0 0 16 16", fill: "none",
    stroke: "white", strokeWidth: 1.6, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  switch (name) {
    case "check":    return <svg {...props}><rect x="2" y="2" width="12" height="12" rx="2"/><path d="M5 8l2 2 4-4"/></svg>;
    case "chart":    return <svg {...props}><path d="M2 12V9l5-5 3 3 4-4v3"/><path d="M2 12h12"/></svg>;
    case "user":     return <svg {...props}><circle cx="8" cy="6" r="3"/><path d="M2 14c0-3 2.7-5 6-5s6 2 6 5"/></svg>;
    case "calendar": return <svg {...props}><rect x="2" y="3" width="12" height="10" rx="1.5"/><path d="M2 7h12M6 3v4M10 3v4"/></svg>;
    case "star":     return <svg {...props}><path d="M8 1L10 5H14L11 8L12 12L8 10L4 12L5 8L2 5H6L8 1Z"/></svg>;
    case "grid":     return <svg {...props}><rect x="2" y="2" width="5" height="5" rx="1"/><rect x="9" y="2" width="5" height="5" rx="1"/><rect x="2" y="9" width="5" height="5" rx="1"/><rect x="9" y="9" width="5" height="5" rx="1"/></svg>;
    default:         return null;
  }
}

export default function LoginPage() {
  const router = useRouter();
  const [email,    setEmail]    = useState("");
  const [password, setPassword] = useState("");
  const [showPwd,  setShowPwd]  = useState(false);
  const [loading,  setLoading]  = useState(false);
  const [error,    setError]    = useState("");

  // Animación CSS inyectada una vez
  useEffect(() => {
    const style = document.createElement("style");
    style.textContent = `
      @keyframes logoFloat {
        0%,100% { transform: translateY(0); }
        50%      { transform: translateY(-8px); }
      }
      @keyframes gradientShift {
        0%,100% { background-position: 0% 50%; }
        50%      { background-position: 100% 50%; }
      }
      @keyframes pulse2 {
        0%,100% { transform: scale(1); opacity: 1; }
        50%      { transform: scale(.85); opacity: .7; }
      }
      @keyframes cardIn {
        from { opacity: 0; transform: translateY(20px) scale(.97); }
        to   { opacity: 1; transform: translateY(0) scale(1); }
      }
      @keyframes spin { to { transform: rotate(360deg); } }
      .logo-float { animation: logoFloat 6s ease-in-out infinite; }
      .logo-float:hover { animation: none; transform: scale(1.04) translateY(-4px) !important; }
      .card-animate { animation: cardIn .6s cubic-bezier(.34,1.2,.64,1) both; }
      .gradient-bar {
        background: linear-gradient(90deg,#C41230,#2557E0,#C41230);
        background-size: 200% 100%;
        animation: gradientShift 3s ease infinite;
      }
      .pulse-dot { animation: pulse2 2s infinite; }
      .spinner {
        display: inline-block; width:16px; height:16px;
        border: 2px solid rgba(255,255,255,.3);
        border-top-color: white; border-radius: 50%;
        animation: spin .7s linear infinite;
      }
      .feature-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 6px 20px rgba(21,53,160,.12);
        border-color: rgba(21,53,160,.25) !important;
      }
      .btn-login:hover:not(:disabled) {
        transform: translateY(-2px);
        box-shadow: 0 10px 32px rgba(196,18,48,.55), 0 4px 12px rgba(196,18,48,.3), inset 0 1px 0 rgba(255,255,255,.15) !important;
      }
      .btn-login:active { transform: translateY(0) !important; }
      .form-input:focus {
        border-color: rgba(37,87,224,.7) !important;
        background: rgba(255,255,255,.10) !important;
        box-shadow: 0 0 0 4px rgba(37,87,224,.18) !important;
      }
      @media (max-width:1023px) {
        .panel-left { display: none !important; }
        .mobile-logo { display: block !important; }
      }
    `;
    document.head.appendChild(style);
    return () => { document.head.removeChild(style); };
  }, []);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res  = await fetch(
        (process.env.NEXT_PUBLIC_API_URL ?? "https://savicol-api-production.up.railway.app") + "/api/v1/auth/login",
        { method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email: email.trim(), password }) }
      );
      const data = await res.json();
      if (data.mfaRequired) { router.push("/mfa"); return; }
      if (data.accessToken) {
        sessionStorage.setItem("access_token", data.accessToken);
        sessionStorage.setItem("user", JSON.stringify(data.user));
        router.push("/");
      } else {
        throw new Error(data.message || "Credenciales inválidas");
      }
    } catch (err: any) {
      setError(err.message || "Error de conexión. Intenta nuevamente.");
    } finally {
      setLoading(false);
    }
  }

  // ── Estilos inline compartidos ─────────────────────────────
  const S = {
    root:   { display:"flex", height:"100vh", width:"100vw",
               fontFamily:"-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif",
               overflow:"hidden", background:"#0A1628" } as React.CSSProperties,

    // Panel izquierdo
    left:   { flex:"0 0 50%", background:"#FFFFFF", display:"flex",
               flexDirection:"column" as const, alignItems:"center",
               justifyContent:"center", position:"relative" as const,
               overflow:"hidden", padding:"40px" },
    bgDeco: { position:"absolute" as const, inset:0,
               backgroundImage:"linear-gradient(rgba(21,53,160,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(21,53,160,.03) 1px,transparent 1px)",
               backgroundSize:"48px 48px", pointerEvents:"none" as const },
    orb1:   { position:"absolute" as const, width:400, height:400,
               top:-100, right:-100, borderRadius:"50%",
               background:"radial-gradient(circle,rgba(21,53,160,.06) 0%,transparent 70%)", pointerEvents:"none" as const },
    orb2:   { position:"absolute" as const, width:300, height:300,
               bottom:-80, left:-80, borderRadius:"50%",
               background:"radial-gradient(circle,rgba(196,18,48,.05) 0%,transparent 70%)", pointerEvents:"none" as const },
    topBar: { position:"absolute" as const, top:0, left:0, right:0,
               height:5, zIndex:2 },
    leftContent: { position:"relative" as const, zIndex:1, display:"flex",
                   flexDirection:"column" as const, alignItems:"center",
                   gap:36, maxWidth:440, width:"100%" },
    logoBlock: { display:"flex", flexDirection:"column" as const,
                 alignItems:"center", gap:14 },
    statusBadge: { display:"inline-flex", alignItems:"center", gap:7,
                   fontSize:10, fontWeight:700, letterSpacing:"0.12em",
                   textTransform:"uppercase" as const, color:"#1535A0",
                   background:"rgba(21,53,160,.07)", border:"1px solid rgba(21,53,160,.15)",
                   borderRadius:20, padding:"5px 14px" },
    featGrid: { display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, width:"100%" },
    featCard: { display:"flex", alignItems:"flex-start", gap:10,
                padding:"12px 14px", borderRadius:10, background:"#F8FAFF",
                border:"1px solid #D8E0F0", transition:"transform .2s,box-shadow .2s,border-color .2s",
                cursor:"default" },
    featIcon: { width:32, height:32, borderRadius:8, flexShrink:0,
                background:"linear-gradient(135deg,#102650,#1A45C8)",
                display:"flex", alignItems:"center", justifyContent:"center",
                boxShadow:"0 2px 8px rgba(21,53,160,.3)" },
    leftFooter: { position:"absolute" as const, bottom:16, left:0, right:0,
                  display:"flex", alignItems:"center", justifyContent:"center",
                  gap:6, fontSize:10, color:"#8899C4", fontWeight:500 },

    // Panel derecho
    right:  { flex:"0 0 50%", position:"relative" as const, display:"flex",
               alignItems:"center", justifyContent:"center",
               padding:"40px 32px", overflow:"hidden",
               background:"linear-gradient(145deg,#0A1628 0%,#0D1F3C 40%,#0C1D45 100%)" },
    rGrid:  { position:"absolute" as const, inset:0,
               backgroundImage:"linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px)",
               backgroundSize:"60px 60px", pointerEvents:"none" as const },
    rOrb1:  { position:"absolute" as const, width:500, height:500,
               top:-150, right:-150, borderRadius:"50%",
               background:"radial-gradient(circle,rgba(196,18,48,.10) 0%,transparent 65%)", pointerEvents:"none" as const },
    rOrb2:  { position:"absolute" as const, width:360, height:360,
               bottom:-100, left:-80, borderRadius:"50%",
               background:"radial-gradient(circle,rgba(37,87,224,.15) 0%,transparent 65%)", pointerEvents:"none" as const },

    // Card glassmorphism
    card:   { position:"relative" as const, zIndex:1, width:"100%", maxWidth:420,
               background:"rgba(255,255,255,.06)",
               backdropFilter:"blur(20px) saturate(180%)",
               WebkitBackdropFilter:"blur(20px) saturate(180%)",
               border:"1px solid rgba(255,255,255,.12)", borderRadius:20,
               overflow:"hidden",
               boxShadow:"0 32px 64px rgba(0,0,0,.35),0 8px 24px rgba(0,0,0,.20),inset 0 1px 0 rgba(255,255,255,.10)" },
    cardBody: { padding:"32px 32px 28px" },
    eyebrow:  { display:"inline-flex", alignItems:"center", gap:8,
                fontSize:10, fontWeight:700, letterSpacing:"0.14em",
                textTransform:"uppercase" as const, color:"rgba(196,18,48,.9)",
                marginBottom:10 },
    label:  { display:"block", fontSize:10, fontWeight:700,
               letterSpacing:"0.10em", textTransform:"uppercase" as const,
               color:"rgba(255,255,255,.50)", marginBottom:8 },
    input:  { width:"100%", height:50, padding:"0 48px",
               background:"rgba(255,255,255,.07)", border:"1.5px solid rgba(255,255,255,.10)",
               borderRadius:12, color:"white", fontSize:14,
               fontFamily:"inherit", outline:"none",
               transition:"border-color .25s,background .25s,box-shadow .25s" },
    btn:    { width:"100%", height:52, border:"none", borderRadius:12,
               background:"linear-gradient(135deg,#C41230 0%,#B01020 50%,#8B0015 100%)",
               color:"white", fontSize:14, fontWeight:800,
               fontFamily:"inherit", letterSpacing:"0.04em",
               textTransform:"uppercase" as const, cursor:"pointer",
               boxShadow:"0 6px 24px rgba(196,18,48,.45),0 2px 8px rgba(196,18,48,.25),inset 0 1px 0 rgba(255,255,255,.15)",
               transition:"transform .15s,box-shadow .15s",
               position:"relative" as const, overflow:"hidden" },
  };

  return (
    <div style={S.root}>

      {/* ══ PANEL IZQUIERDO — BLANCO ══ */}
      <aside className="panel-left" style={S.left}>
        {/* Barra acento top */}
        <div className="gradient-bar" style={S.topBar} />
        <div style={S.bgDeco} />
        <div style={S.orb1} />
        <div style={S.orb2} />

        <div style={S.leftContent}>

          {/* Logo centrado sin fondo */}
          <div style={S.logoBlock}>
            <img
              className="logo-float"
              src={LOGO_URI}
              alt="AP Audit Platform Software"
              width={300} height={200}
              style={{ width:"min(300px,70%)", height:"auto", objectFit:"contain",
                filter:"drop-shadow(0 8px 24px rgba(21,53,160,.15)) drop-shadow(0 2px 8px rgba(196,18,48,.10))" }}
            />
            <div style={S.statusBadge}>
              <span className="pulse-dot"
                style={{ width:7, height:7, borderRadius:"50%", background:"#22C55E",
                  boxShadow:"0 0 0 3px rgba(34,197,94,.2)", display:"inline-block" }} />
              Sistema activo · Producción 2026
            </div>
          </div>

          {/* Características del sistema */}
          <div style={S.featGrid}>
            {FEATURES.map((f) => (
              <div key={f.title} className="feature-card" style={S.featCard}>
                <div style={S.featIcon}><IconSVG name={f.icon} /></div>
                <div style={{ display:"flex", flexDirection:"column", gap:2 }}>
                  <span style={{ fontSize:11, fontWeight:700, color:"#1a2744", lineHeight:1.3 }}>{f.title}</span>
                  <span style={{ fontSize:10, color:"#4A5980", lineHeight:1.4 }}>{f.desc}</span>
                </div>
              </div>
            ))}
          </div>

        </div>

        <div style={S.leftFooter}>
          <span>© 2026 Savicol S.A.S.</span>
          <span style={{ opacity:.4 }}>·</span>
          <span>Control Interno</span>
          <span style={{ opacity:.4 }}>·</span>
          <span>Auditoría Corporativa</span>
        </div>
      </aside>

      {/* ══ PANEL DERECHO — AZUL REY ══ */}
      <main style={S.right}>
        <div style={S.rGrid} />
        <div style={S.rOrb1} />
        <div style={S.rOrb2} />

        {/* Card glassmorphism */}
        <div className="card-animate" style={S.card}>

          {/* Barra gradiente top */}
          <div className="gradient-bar" style={{ height:4 }} />

          <div style={S.cardBody}>

            {/* Logo móvil */}
            <img
              className="mobile-logo"
              src={LOGO_URI}
              alt="AP Audit"
              width={140}
              style={{ display:"none", margin:"0 auto 28px", width:140, height:"auto",
                filter:"brightness(10) saturate(0)" }}
            />

            {/* Eyebrow */}
            <div style={S.eyebrow}>
              <span style={{ width:24, height:2, background:"#C41230",
                borderRadius:2, display:"inline-block" }} />
              Savicol S.A.S.
            </div>

            <h1 style={{ fontSize:28, fontWeight:900, color:"white",
              letterSpacing:"-0.02em", lineHeight:1.1, marginBottom:6 }}>
              Iniciar Sesión
            </h1>
            <p style={{ fontSize:13, color:"rgba(255,255,255,.45)", marginBottom:28 }}>
              Accede con tus credenciales corporativas
            </p>

            {/* Error */}
            {error && (
              <div style={{ display:"flex", alignItems:"center", gap:8,
                background:"rgba(196,18,48,.15)", border:"1px solid rgba(196,18,48,.30)",
                borderRadius:10, padding:"10px 14px", marginBottom:18,
                fontSize:12, color:"#FCA5A5" }}>
                ⚠ {error}
              </div>
            )}

            <form onSubmit={handleSubmit} noValidate>

              {/* Email */}
              <div style={{ marginBottom:18 }}>
                <label style={S.label}>Correo corporativo</label>
                <div style={{ position:"relative" }}>
                  <svg style={{ position:"absolute", left:14, top:"50%",
                    transform:"translateY(-50%)", width:16, height:16,
                    color:"rgba(255,255,255,.30)", pointerEvents:"none" }}
                    viewBox="0 0 16 16" fill="none" stroke="currentColor"
                    strokeWidth={1.5} strokeLinecap="round">
                    <rect x="1.5" y="3.5" width="13" height="9" rx="1.5"/>
                    <path d="M1.5 5.5l6.5 4 6.5-4"/>
                  </svg>
                  <input className="form-input" type="email"
                    value={email} onChange={e => setEmail(e.target.value)}
                    placeholder="correo@savicol.com.co"
                    autoComplete="email" required
                    style={{ ...S.input, paddingLeft:48 }} />
                </div>
              </div>

              {/* Password */}
              <div style={{ marginBottom:18 }}>
                <label style={S.label}>Contraseña</label>
                <div style={{ position:"relative" }}>
                  <svg style={{ position:"absolute", left:14, top:"50%",
                    transform:"translateY(-50%)", width:16, height:16,
                    color:"rgba(255,255,255,.30)", pointerEvents:"none" }}
                    viewBox="0 0 16 16" fill="none" stroke="currentColor"
                    strokeWidth={1.5} strokeLinecap="round">
                    <rect x="3" y="7" width="10" height="7" rx="1.5"/>
                    <path d="M5.5 7V5a2.5 2.5 0 015 0v2"/>
                  </svg>
                  <input className="form-input"
                    type={showPwd ? "text" : "password"}
                    value={password} onChange={e => setPassword(e.target.value)}
                    placeholder="••••••••••••"
                    autoComplete="current-password" required
                    style={{ ...S.input, paddingLeft:48, paddingRight:48 }} />
                  <button type="button" onClick={() => setShowPwd(!showPwd)}
                    style={{ position:"absolute", right:14, top:"50%",
                      transform:"translateY(-50%)", background:"none", border:"none",
                      cursor:"pointer", color:"rgba(255,255,255,.35)", padding:4, lineHeight:0,
                      transition:"color .2s" }}>
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none"
                      stroke="currentColor" strokeWidth={1.5} strokeLinecap="round"
                      style={{ opacity: showPwd ? 0.5 : 1 }}>
                      {showPwd
                        ? <><path d="M2 2l12 12M7 3.1A6 6 0 0114.5 8c-.7 1.7-2 3-3.5 3.8M1.5 8C3 4.5 5 3 8 3c.3 0 .7 0 1 .1M10.5 10.5A4 4 0 014 8"/></>
                        : <><path d="M1.5 8C3 4.5 5 3 8 3s5 1.5 6.5 5c-1.5 3.5-3.5 5-6.5 5s-5-1.5-6.5-5z"/><circle cx="8" cy="8" r="2"/></>
                      }
                    </svg>
                  </button>
                </div>
              </div>

              {/* MFA */}
              <div style={{ display:"flex", alignItems:"center", gap:8,
                fontSize:11, color:"rgba(255,255,255,.32)",
                background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.07)",
                borderRadius:8, padding:"9px 13px", marginBottom:22 }}>
                <svg width="13" height="13" viewBox="0 0 16 16" fill="none"
                  stroke="rgba(196,18,48,.65)" strokeWidth={1.5} strokeLinecap="round"
                  style={{ flexShrink:0 }}>
                  <rect x="3" y="7" width="10" height="7" rx="1.5"/>
                  <path d="M5.5 7V5a2.5 2.5 0 015 0v2"/>
                </svg>
                Autenticación multifactor (MFA) requerida para todos los roles
              </div>

              {/* Botón */}
              <button type="submit" disabled={loading}
                className="btn-login" style={{ ...S.btn,
                  opacity: loading ? 0.7 : 1,
                  cursor: loading ? "not-allowed" : "pointer" }}>
                <span style={{ position:"relative", zIndex:1,
                  display:"flex", alignItems:"center", justifyContent:"center", gap:8 }}>
                  {loading
                    ? <><span className="spinner" />&nbsp;Verificando...</>
                    : <>
                        <svg width="16" height="16" viewBox="0 0 16 16" fill="none"
                          stroke="currentColor" strokeWidth={1.8} strokeLinecap="round">
                          <path d="M10 8H2m5-3 3 3-3 3"/>
                          <path d="M8 3h4a1 1 0 011 1v8a1 1 0 01-1 1H8"/>
                        </svg>
                        Acceder a la plataforma
                      </>
                  }
                </span>
              </button>
            </form>

            {/* Footer card */}
            <div style={{ marginTop:22, paddingTop:18,
              borderTop:"1px solid rgba(255,255,255,.07)",
              display:"flex", alignItems:"center", justifyContent:"space-between" }}>
              <a href="#" style={{ fontSize:12, color:"rgba(255,255,255,.35)",
                textDecoration:"none" }}>¿Problemas de acceso?</a>
              <div style={{ display:"flex", alignItems:"center", gap:5,
                fontSize:10, fontWeight:600, color:"rgba(255,255,255,.28)",
                textTransform:"uppercase", letterSpacing:"0.06em" }}>
                <span style={{ width:6, height:6, borderRadius:"50%",
                  background:"#22C55E", boxShadow:"0 0 0 2px rgba(34,197,94,.2)",
                  display:"inline-block" }} />
                Conexión segura
              </div>
            </div>

          </div>
        </div>
      </main>
    </div>
  );
}
